SELECT 
FROM prc_operation WHERE is_deleted = 0

    AND (operation_code LIKE CONCAT('%', #{keyword}, '%')
         OR operation_name LIKE CONCAT('%', #{keyword}, '%'))


    AND operation_code LIKE CONCAT('%', #{operationCode}, '%')


    AND operation_name LIKE CONCAT('%', #{operationName}, '%')


    AND operation_type = #{operationType}


    AND status = #{status}

ORDER BY id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM prc_operation WHERE is_deleted = 0
AND (operation_code LIKE CONCAT('%', #{keyword}, '%') OR operation_name LIKE CONCAT('%', #{keyword}, '%'))
AND operation_code LIKE CONCAT('%', #{operationCode}, '%')
AND operation_name LIKE CONCAT('%', #{operationName}, '%')
AND operation_type = #{operationType}
AND status = #{status}
